public void useOfListOrSets()
{
    List listOfStrings = new List(Types::String);
    listOfStrings.addEnd('manolo');
    listOfStrings.addEnd('Pongo');

    ListIterator literator = new ListIterator(listOfStrings);
    while(literator.more())
    {
        literator.value();
        literator.next();
    }

    Set setOfStrings = new Set(Types::String);

    setOfStrings.add('manolo');
    setOfStrings.add('Pongo');

    SetIterator siterator = new SetIterator(setOfStrings);

    while(siterator.more())
    {
        siterator.value();
        siterator.next();
    }
}

