public void UseOfContainers()
{
    container fieldsCon;
    AIBBookTable bookTable;
    int i = 1;

    while select bookTable
    {
        fieldsCon = conIns(fieldsCon, i, bookTable);
        fieldsCon = conIns(fieldsCon, i+1, bookTable.Name);

        i+=2;
    }

    bookTable = conPeek(fieldsCon, 3);
    Name name = conPeek(fieldsCon, 4);
}

public void UseOfContainers2()
{
    container fieldsCon;
    AIBBookTable bookTable;
    int i = 1;

    while select bookTable
    {
        fieldsCon += bookTable;
        fieldsCon += bookTable.Name;


        i+=2;
    }

    container containerDe0 = ['manolo', 5, 35];

    fieldsCon += containerDe0;
    fieldsCon += [containerDe0];

    str manolo;
    int num1, num2;
    [manolo, num1, num2] = containerDe0;
}
